<script setup>
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { BookOpen, ArrowLeft, FileText, Download, Play, CircleCheck, Target, CalendarPlus, ChevronRight, RefreshCw } from 'lucide-vue-next';
import { useAuthStore } from '~/stores/api/auth';
import { useUserMaterialsStore } from '~/stores/api/userMaterials';
import { canAccessPage } from '~/utils/roles';
definePageMeta({ layout: 'default' });
const auth = useAuthStore(), store = useUserMaterialsStore(), route = useRoute();
const ready = ref(false), fileUrl = ref(''), readingProgress = ref(0), downloading = ref(false);
const material = computed(() => store.selectedMaterial?.material);
const isPdf = computed(() => material.value?.file_mime === 'application/pdf');
const applicableSubtests = computed(() => material.value?.subtests?.map(entry => entry.code) ?? (material.value?.subtest ? [material.value.subtest] : []));
const subtestLabel = computed(() => applicableSubtests.value.join(', '));
const card = 'min-w-0 rounded-3xl border border-soft-blue bg-surface-white p-4 shadow-sm sm:p-6';
const statusText = value => ({ not_started: 'Belum Dimulai', in_progress: 'Sedang Dipelajari', completed: 'Selesai' })[value] || 'Belum Dimulai';
watch(material, value => { readingProgress.value = Number(value?.progress || 0); });
async function load() { if (fileUrl.value) { URL.revokeObjectURL(fileUrl.value); fileUrl.value = ''; } await store.fetchMaterialDetail(route.params.id); }
async function openFile() { const detail = await store.startMaterial(route.params.id); if (!detail) return; const blob = await store.fetchFile(route.params.id); if (blob) { if (fileUrl.value) URL.revokeObjectURL(fileUrl.value); fileUrl.value = URL.createObjectURL(blob); } }
async function downloadFile() { downloading.value = true; try { const blob = await store.fetchFile(route.params.id); if (!blob) return; const url = URL.createObjectURL(blob), anchor = document.createElement('a'); anchor.href = url; anchor.download = material.value?.file_name || 'materi'; document.body.append(anchor); anchor.click(); anchor.remove(); setTimeout(() => URL.revokeObjectURL(url), 60000); } finally { downloading.value = false; } }
async function saveProgress() { await store.updateProgress(route.params.id, readingProgress.value); }
async function complete() { await store.completeMaterial(route.params.id); }
onMounted(async () => { auth.initializeAuth(); if (!auth.token) return navigateTo('/login'); const user = await auth.fetchCurrentUser(); if (Number(user?.role) !== 2 || !canAccessPage(user?.role, 'materials.read')) return navigateTo('/dashboard'); ready.value = true; await load(); });
watch(() => route.params.id, () => { if (ready.value) load(); });
onBeforeUnmount(() => { if (fileUrl.value) URL.revokeObjectURL(fileUrl.value); });
</script>
<template>
  <div class="mx-auto w-full max-w-[1500px] min-w-0 px-4 py-5 text-on-surface sm:px-6 sm:py-7 lg:px-8"><NuxtLink to="/materials" class="mb-4 inline-flex items-center gap-2 text-sm font-semibold text-primary-container"><ArrowLeft class="h-4 w-4" /> Kembali ke Materi</NuxtLink><div v-if="store.error" role="alert" class="mb-4 flex items-center justify-between gap-3 rounded-2xl border border-rose-200 bg-white p-4 text-sm text-rose-700"><span>{{ store.error }}</span><button class="inline-flex items-center gap-2 font-semibold" @click="load"><RefreshCw class="h-4 w-4" /> Coba Lagi</button></div><div v-if="!ready || store.isLoadingDetail" class="grid gap-4 lg:grid-cols-12" aria-label="Memuat detail materi"><div class="h-96 animate-pulse rounded-3xl bg-slate-200 lg:col-span-8" /><div class="h-72 animate-pulse rounded-3xl bg-slate-200 lg:col-span-4" /></div><template v-else-if="material"><header class="mb-5"><span class="rounded-full bg-pale-blue px-3 py-1 text-xs font-semibold text-primary-container">{{ subtestLabel }}</span><h1 class="mt-3 text-2xl font-bold sm:text-3xl">{{ material.title }}</h1><p class="mt-1 max-w-3xl text-sm text-on-surface-variant">{{ material.description || 'Pelajari dokumen materi SNBT ini dan catat progres bacamu.' }}</p></header><div class="grid min-w-0 gap-4 lg:grid-cols-12"><main class="min-w-0 space-y-4 lg:col-span-8"><section :class="card"><div class="mb-4 flex items-center gap-2"><FileText class="h-5 w-5 text-primary-container" /><h2 class="font-bold">Isi Materi</h2></div><p class="text-sm text-on-surface-variant">{{ material.file_name }} · {{ material.category }} · {{ Math.max(1, Math.round((material.file_size || 0) / 1024)) }} KB</p><div class="mt-4 flex flex-wrap gap-2"><button :disabled="store.isUpdatingProgress" class="inline-flex items-center gap-2 rounded-xl bg-primary-container px-4 py-2 text-sm font-semibold text-white disabled:opacity-50" @click="openFile"><Play class="h-4 w-4" /> {{ material.status === 'not_started' ? 'Mulai Membaca' : 'Buka Materi' }}</button><button :disabled="downloading" class="inline-flex items-center gap-2 rounded-xl border border-soft-blue px-4 py-2 text-sm font-semibold text-primary-container" @click="downloadFile"><Download class="h-4 w-4" /> Unduh Dokumen</button></div><iframe v-if="fileUrl && isPdf" :src="fileUrl" :title="`Dokumen ${material.title}`" class="mt-5 h-[65vh] w-full rounded-xl border border-soft-blue" /><p v-else-if="fileUrl" class="mt-4 rounded-xl bg-surface-container-low p-4 text-sm text-on-surface-variant">Format dokumen ini diunduh untuk dibaca di aplikasi perangkatmu.</p><div v-else class="mt-5 flex min-h-40 items-center justify-center rounded-2xl bg-surface-container-low p-5 text-center text-sm text-outline">Buka atau unduh dokumen untuk mulai belajar.</div></section><section :class="card"><h2 class="font-bold">Topik / Dokumen</h2><div v-for="topic in store.selectedMaterial?.topics || []" :key="topic.topic_id" class="mt-3 flex items-center justify-between rounded-xl bg-surface-container-low p-3 text-sm"><span>{{ topic.title }}</span><span>{{ topic.completed ? 'Selesai' : 'Belum selesai' }}</span></div></section><div class="grid gap-3 sm:grid-cols-2"><NuxtLink v-if="store.selectedMaterial?.previous_material" :to="`/materials/${store.selectedMaterial.previous_material.material_id}`" class="rounded-2xl border border-soft-blue p-4 text-sm"><span class="text-xs text-outline">Materi Sebelumnya</span><strong class="mt-1 block">{{ store.selectedMaterial.previous_material.title }}</strong></NuxtLink><NuxtLink v-if="store.selectedMaterial?.next_material" :to="`/materials/${store.selectedMaterial.next_material.material_id}`" class="rounded-2xl border border-soft-blue p-4 text-sm"><span class="text-xs text-outline">Materi Berikutnya</span><strong class="mt-1 flex items-center justify-between">{{ store.selectedMaterial.next_material.title }} <ChevronRight class="h-4 w-4" /></strong></NuxtLink></div></main><aside class="min-w-0 space-y-4 lg:col-span-4"><section :class="card"><div class="mb-3 flex items-center gap-2"><BookOpen class="h-5 w-5 text-primary-container" /><h2 class="font-bold">Progress Materi</h2></div><p class="text-sm text-on-surface-variant">{{ statusText(material.status) }}</p><strong class="mt-2 block text-2xl text-primary-container">{{ material.progress }}%</strong><div class="mt-2 h-3 rounded-full bg-surface-container"><div class="h-full rounded-full bg-primary-container" :style="{ width: `${material.progress}%` }" /></div><template v-if="material.status !== 'completed'"><label class="mt-5 block text-xs font-semibold">Progress baca yang kamu catat: {{ readingProgress }}%<input v-model.number="readingProgress" type="range" min="0" max="100" step="5" class="mt-2 w-full accent-blue-600" /></label><button :disabled="store.isUpdatingProgress" class="mt-3 w-full rounded-xl border border-primary-container px-3 py-2 text-sm font-semibold text-primary-container disabled:opacity-50" @click="saveProgress">Simpan Progress</button><button :disabled="store.isUpdatingProgress" class="mt-2 inline-flex w-full items-center justify-center gap-2 rounded-xl bg-primary-container px-3 py-2 text-sm font-semibold text-white disabled:opacity-50" @click="complete"><CircleCheck class="h-4 w-4" /> Tandai Materi Selesai</button></template><p v-else class="mt-4 text-sm text-primary-container">Materi ini sudah selesai. Kamu tetap bisa membacanya kembali.</p></section><section :class="card"><div class="mb-3 flex items-center gap-2"><Target class="h-5 w-5 text-primary-container" /><h2 class="font-bold">Practice Terkait</h2></div><p class="text-sm text-on-surface-variant">{{ material.practice_question_count }} soal aktif tersedia untuk materi ini.</p><div v-if="material.practice_question_count" class="mt-4 flex flex-wrap gap-x-4 gap-y-2"><NuxtLink v-for="code in applicableSubtests" :key="code" :to="`/practice?subtest=${code}&material_id=${material.material_id}`" class="inline-flex items-center gap-2 text-sm font-semibold text-primary-container">Latihan {{ code }} <ChevronRight class="h-4 w-4" /></NuxtLink></div><p v-else class="mt-3 text-xs text-outline">Soal latihan belum tersedia.</p></section><section :class="card"><div class="mb-3 flex items-center gap-2"><CalendarPlus class="h-5 w-5 text-primary-container" /><h2 class="font-bold">Rencanakan Belajar</h2></div><p class="text-sm text-on-surface-variant">Tambahkan materi ini ke jadwal belajarmu.</p><NuxtLink :to="`/study-plan?type=material&material_id=${material.material_id}`" class="mt-4 inline-flex items-center gap-2 text-sm font-semibold text-primary-container">Tambahkan ke Study Plan <ChevronRight class="h-4 w-4" /></NuxtLink></section></aside></div></template><div v-else class="rounded-2xl bg-surface-container-low p-8 text-center text-sm text-outline">Materi aktif tidak ditemukan.</div></div>
</template>
